// bytes the extension ships. Those four reach for `chrome.storage.local` and
// `chrome.i18n`, which do not exist outside an extension — so rather than forking
// them (four files that would then drift), the app supplies the two APIs they use.
//
// Deliberately NOT a general-purpose polyfill. It implements exactly what those files
// call and nothing else, because a shim that pretends to be more than it is invites
// code to depend on behaviour that was never really there.
//
// 2026-09-06 起多了一样：`storage.onChanged`。它是 App 侧**唯一的设置总线** —— 之前没有
// 它，review.js 在 bundle 加载时读一次设置之后就再没人能告诉它「变了」，App 只能靠每个
// 设置控件手写显式重绘，一键配置 / 朗读模式 / 自动播放三处漏了，症状是「配好语音 key
// 返回，播客入口与 ▶ 仍不出现，要重启 App」。消费者（review.js、driving.js）只订阅它。
//
// Must be FIRST in the bundle — the modules below it read `chrome` at load time.

(() => {
  if (typeof window.chrome !== 'undefined' && window.chrome.storage) return;

  // ─── storage.local, backed by localStorage ────────────────────────────────
  // Verified available on the app's file:// origin (verification-spec, Stage 2 spike).
  // The callback shape is the important part: `page-settings.js` inspects
  // `chrome.runtime.lastError` and `drain.js` passes key arrays, so a Promise-only
  // shim would silently do nothing in both.
  const PREFIX = 'mt:';
  const readAll = () => {
    const out = {};
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (k && k.indexOf(PREFIX) === 0) {
        try { out[k.slice(PREFIX.length)] = JSON.parse(localStorage.getItem(k)); } catch (_) {}
      }
    }
    return out;
  };

  // ─── App-side defaults that must exist BEFORE the first read ─────────────
  // **这里曾经同步播种 `ttsMode: 'assist'`，2026-09-04 去掉了。**
  //
  // 去掉的理由：语音不再默认可用（`LearnTTS.DEFAULTS.engineId` 已改为 ''），
  // 而 'assist' 的意思是「显示原文，可点播放」—— 在没有引擎的情况下那就是一个
  // **点了必然失败的播放键**，仓库里有前科。默认回到 'off'，与扩展一致。
  //
  // ⚠️ **但那段注释记的竞态仍然成立，别把它一起丢掉**：`review.js` 在 bundle
  // 加载时**只读一次**设置，而 `AppSettings.ensureDefaults` 是异步的、会输掉这场
  // 竞速。所以将来若又需要给 App 一个**非默认**的初始值，它必须播种在**这里**
  // （同步、在 review.js 之前），而不是 ensureDefaults 里。

  // ─── storage.onChanged —— 与真 API 同形：set/remove 之后**异步**派发
  // {key: {oldValue, newValue}}, 'local'；值没变的键不发。异步是为了写入方不会在自己的
  // set() 里被重入。一个监听器抛错不能拖累其它监听器 —— 设置页保存时挂掉复习页不是选项。
  const listeners = new Set();
  const onChanged = {
    addListener(fn) { if (typeof fn === 'function') listeners.add(fn); },
    removeListener(fn) { listeners.delete(fn); },
    hasListener(fn) { return listeners.has(fn); },
  };
  const emit = (changes) => {
    if (!Object.keys(changes).length || !listeners.size) return;
    setTimeout(() => {
      for (const fn of [...listeners]) {
        try { fn(changes, 'local'); }
        catch (e) { try { console.error('[chrome-shim] onChanged listener threw', e); } catch (_) {} }
      }
    }, 0);
  };
  const parse = (raw) => { try { return JSON.parse(raw); } catch (_) { return undefined; } };

  const storage = {
    onChanged,
    get(query, cb) {
      const all = readAll();
      let out;
      if (query == null) out = all;
      else if (typeof query === 'string') out = ({ [query]: all[query] });
      else if (Array.isArray(query)) { out = {}; for (const k of query) if (k in all) out[k] = all[k]; }
      else { out = {}; for (const k of Object.keys(query)) out[k] = (k in all) ? all[k] : query[k]; }
      // Asynchronous on purpose. The real API is, and callers written against a
      // synchronous fake break the moment they meet the real one.
      setTimeout(() => cb && cb(out), 0);
    },
    set(items, cb) {
      const changes = {};
      for (const [k, v] of Object.entries(items || {})) {
        const prev = localStorage.getItem(PREFIX + k);
        let next;
        try { next = JSON.stringify(v); } catch (_) { continue; }
        try { localStorage.setItem(PREFIX + k, next); } catch (_) { continue; }
        if (prev === next) continue;
        const c = {};
        if (prev != null) c.oldValue = parse(prev);
        c.newValue = v;
        changes[k] = c;
      }
      // 回调先于派发排队：调用方 await 完 set() 时监听器还没跑，与真 API 一致。
      setTimeout(() => cb && cb(), 0);
      emit(changes);
    },
    remove(keys, cb) {
      const changes = {};
      for (const k of [].concat(keys || [])) {
        const prev = localStorage.getItem(PREFIX + k);
        localStorage.removeItem(PREFIX + k);
        if (prev == null) continue;
        changes[k] = { oldValue: parse(prev) };
      }
      setTimeout(() => cb && cb(), 0);
      emit(changes);
    },
  };

  window.chrome = Object.assign(window.chrome || {}, {
    storage: { local: storage, onChanged },
    runtime: {
      // Always undefined: nothing here can produce an extension-messaging error, and
      // `page-settings.js` reads it on every get.
      lastError: undefined,
      getURL: (p) => p,
      // The review page's 「设置」 link. Stage 4 gives the app its own settings; until
      // then this must not throw and must not open a browser window pointing at an
      // extension URL that does not exist here.
      openOptionsPage: () => { throw new Error('app has no options page yet'); },
    },
    i18n: {
      // `i18n.js` consults the bundled MT_I18N_MESSAGES table FIRST and only falls
      // through to chrome.i18n, so returning '' here is not a loss — it just makes the
      // bundled table authoritative, which on a single-locale app shell is correct.
      getMessage: () => '',
      getUILanguage: () => navigator.language || 'zh-CN',
    },
  });
})();


// ─── extension/learn/backend.config.js ───────────────────────────
// learn/backend.config.js — where the optional sync backend lives.
// See docs/learning-design.md §8.4.1.
//
// EVERYTHING here is public by design: the URL is a hostname and the key is the
// *publishable* anon key, which grants nothing on its own — every table is behind RLS
// keyed on `auth.uid()`, so an anon key with no session can read and write nothing.
// It ships in the extension bundle, which anyone can unzip; that is fine and expected.
// A key that must stay secret must never appear in this file.
//
// This is also the whole "which backend" decision, in one object. §8.4.1 explains why
// the client is written so that changing it is a one-file change.

var MT_BACKEND = {
  // ─── SHIPPING SWITCH ─────────────────────────────────────────────────────
  // true since v1.4.0 (Gate B, 2026-08-09): sync is PUBLIC. The flip landed in
  // the same commit as the honest privacy copy — README ×2, the in-product
  // learn_section_hint ×11 locales, and the Firefox data_collection_permissions
  // growing to three entries — exactly as learning-design §10 required. The
  // build gates that used to block this flag now guard the OPPOSITE direction:
  // enabled:true with any stale "never uploaded / no account" sentence anywhere
  // in the repo fails the build (see build.js validateManifest, Gate B block).
  //
  // The CHINA flavor's EXTENSION ships with this flipped back to false at build
  // time (build.js china override). The China HOST APP, however, ships the one
  // shared app bundle — enabled:true, sign-in included — by explicit decision
  // (2026-08-17, App Review Route A: reviewers require a username+password demo
  // account, so the login stays). Known asymmetry: a China user's extension does
  // not upload, so the app's sync only pulls what other (global-flavor) devices
  // pushed. Unifying the china extension's sync is a separate decision with its
  // own PIPL/cross-border gate.
  //
  // Sign-in stays optional: signed out, every feature except multi-device sync
  // works fully and locally (§8.2 stance — sync is an upgrade, not a gate).
  enabled: true,

  // Dedicated project, Tokyo (ap-northeast-1) — 2026-08-04. Tokyo rather than the
  // us-east-1 the other projects use: sync is not latency-critical, but the users
  // are, and from mainland China us-east-1 is ~250-350ms and unreliable where Tokyo
  // is ~50-80ms. Region cannot be changed after creation, so it is a decision, not
  // a default.
  url: 'https://cavezcufztzqsohpjmup.supabase.co',
  anonKey: 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImNhdmV6Y3VmenR6cXNvaHBqbXVwIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODU4MTczNTAsImV4cCI6MjEwMTM5MzM1MH0.VdL1B_jYLySEkhecL6WHOLV_vYbnRItpciFx7ZSxO4M',
  table: 'bt_chunks',
  quotaBytes: 50 * 1024 * 1024,

  // 后端**真的开着**的第三方登录（§8.4.1.2）。界面只提供这里列出的。
  //
  // 为什么要有这张表：一个 provider 在 Supabase 那边没配时，点它会跳到一个
  // 「Unsupported provider」的错误页 —— 一个必然失败的按钮，和「点了没反应」
  // 是同一类。而「配没配」是**后端的状态**，客户端猜不出来，只能被告知。
  //
  // 加一个 provider 的顺序永远是：先在 Supabase 配好并实测授权入口 302 到对的地方，
  // 再把它写进这张表。反过来做，就是发一个坏按钮出去。
  //   apple  —— 2026-09-03 配好（Services ID + secret，实测 302 到 appleid.apple.com）
  //   google —— 2026-09-03 配好（OAuth client 950198135110-…，实测 302 到
  //             accounts.google.com 且 client_id 与本地那份逐字一致）
  //
  // 排序就是界面上的排序。Apple 在前：按下载数据用户几乎全在苹果设备上，而在那些
  // 设备上 Sign in with Apple 是系统级的一次点击，Google 要走一次浏览器往返。
  providers: ['apple', 'google'],

  // 手机号验证码。**还没接通** —— Supabase 的 Send SMS Hook 与阿里云 PNVS 都没配。
  // 界面按这个值决定说不说「手机号」；auth.js 那一侧早就支持了，但**能力不等于承诺**：
  // 在没接通时把「邮箱或手机号」写在标签上，是让用户填一个必然失败的东西。
  //
  // 接通之后这里也**不能直接写 true** —— PNVS 只发中国大陆号码（+86）。对一个法国
  // 用户说「手机号」同样是假话。所以它的取值是**地域相关**的：
  //   'cn'   —— 只在中国版构建里提供（那个 flavor 的用户几乎必然是 +86）
  //   true   —— 所有地区都提供（只有换成一家全球可达的短信服务之后才成立）
  //   false  —— 不提供（现在）
  // 判据永远是「这条路对**这个**用户真的能走通吗」，不是「我们实现了吗」。
  phoneOtp: false,

  // ─── 中国版的境内后端（§C，2026-09-05）──────────────────────────────────
  //
  // 上面那个 `url` 在东京（ap-northeast-1）。中国版 **App** 今天就在打它 ——
  // 也就是说中国版现在有数据出境，而 App Store 中国区指向的隐私政策写着
  // 「绝不上传」。境内后端要解决的是这件事的前一半（数据去哪），
  // 后一半（怎么说）在 `~/belliedmonkey-cc/privacy-cn.html`。
  //
  // 形状是「一台轻量服务器跑整套」：Postgres + GoTrue + PostgREST + 反代。
  // **协议一个字节不变** —— 客户端对 Supabase 的特有依赖近乎为零（没有
  // supabase-js、没有 Storage/Realtime），它说的是标准 GoTrue + PostgREST，
  // 而 `auth.uid()` / `auth.users` 是 GoTrue 的产物不是 Supabase 独有。
  // 所以这里只换地址与 key，`supabase/schema.sql` 原样复用。
  // 部署契约见 `deploy/china/README.md`。
  //
  // ⚠️ **`ready` 是这个块存在的全部理由。**
  //
  // 机器、备案、SMTP 三件事任何一件没就绪，切过去就是把中国版所有用户送进一个
  // 连不上的地址 —— 那比现在的状态坏得多。所以：
  //
  //   ready: false —— 构建行为**与从前逐字相同**（中国版扩展 sync 关闭）。
  //                   这是今天的值，代码与门禁先落地，不动运行时。
  //   ready: true  —— 中国版产物的 url/anonKey 换成下面这两个，且**不再关 sync**。
  //
  // 翻它之前必须全部为真（`deploy/china/README.md` 有逐条判据）：
  //   1. 服务器上五条真实链路都跑通了（Apple 登录 · 邮箱 OTP · push · pull · 删号）
  //   2. `url` 那个域名的 ICP 备案已通过，且接入商就是这台机器所在的云厂商
  //   3. `anonKey` 是该后端 GoTrue 同一个 JWT secret 签出的 `role: anon` 长期 token
  //
  // 只有一处写死了「境内」这件事：门禁要求 `url` 不是 *.supabase.co
  // （见 test/backend-config.test.js）—— 否则「切过去了」会是一句假话。
  china: {
    ready: false,
    url: '',
    anonKey: '',
  },

  // ─── 免费额度（§8.10，2026-09-08）────────────────────────────────────────
  //
  // 每个**已登录**用户一份封顶 0.2 美元的额度。用户拿到的是一枚**令牌**
  // （`bmg_` + 43 字符），不是提供方的 key —— 提供方的 key 只在边缘函数
  // `bt-relay` 的环境变量里，永不离开服务器。请求经我们的中继转发并计量。
  //
  // 这与 AGENTS 规则 2「免费路径不需要我们的服务器」并不冲突，因为它**不是免费
  // 路径**：自带 key 与免费 Google 引擎一个字节都没变，额度是登录带来的附加福利。
  // 用户 2026-09-08 的原话：「额度不走自带 key，额度走我们服务端。我没有违反免费承诺。」
  //
  // ⚠️ **`enabled` 是这个块存在的全部理由**，同 `china.ready` 的先例：
  //   false —— 构建产物里**没有** MT_GRANT，客户端所有额度分支都取不到 spec，
  //            行为与从前逐字相同。这是今天的值：代码与门禁先落地，不动运行时。
  //   true  —— 全球版发射 MT_GRANT，领取入口出现。翻它是 G6 的动作，
  //            前置是 README ×2 与两站隐私的 Gate F 文案**同版**上线。
  //
  // 中国版**恒为 null**，不是「关着」而是「不存在」：中国用户的原文会经东京中转，
  // 而境内后端未就绪（同 `china.ready` 的三件外部事）。中国版走的是另一条路 ——
  // 引导用户去领百炼官方的免费额度，那份额度是阿里云给的，不经我们的手。
  grant: {
    enabled: true,
    vendor: 'openrouter',
    // 披露文案里要显示的名字。**只写这一处** —— Gate F 那段话要出现在 README ×2、
    // 两个站点、12 份 locale 的卡上；把厂商名抄进那些地方就是十几份会漂的副本，
    // 而这个仓库已经为「抄下来的名字不再跟着注册表走」付过一次学费（DeepSeek 的
    // 提示写死了模型名，API 早就不认了还在那儿）。文案里用 {vendor} 占位。
    vendorLabel: 'OpenRouter',
    limitUsd: 0.2,
    // 中继的三个地址。**在这里由 url 拼出来，不在别处再写一遍主机名** ——
    // 换后端时只改上面那个 `url`。生成到产物里的是完整地址，运行时原样使用
    // （wire-format 的「地址原样请求」承诺，domain-design §7）。
    relayPath: '/functions/v1/bt-relay',
    china: { ready: false },
  },
};

if (typeof module !== 'undefined' && module.exports) module.exports = MT_BACKEND;


// ─── extension/learn/page-settings.js ────────────────────────────
// learn/page-settings.js — reading settings from an EXTENSION PAGE, and knowing
// when that read FAILED as opposed to came back empty.
//
// Found with Safari Web Inspector against the simulator's options page, 2026-08-05,
// after two wrong guesses. The two forms of the same call disagree:
//
//   callback form:  cb(undefined)          ← fires, hands back nothing, says nothing
//   promise form:   rejects with
//     "Invalid call to browser.storage.local.get().
//      Failed to create extension storage directory."
//
// So the storage layer was BROKEN, and the callback form reported that as an empty
// result. Our code then did the only thing it could with an empty result: painted
// defaults. The user saw their provider and API key silently revert to the free
// channel — indistinguishable, from the outside, from never having saved them.
//
// That silence is the part that is ours to fix. Prefer the promise form because it is
// the only one that tells the truth; fall back to the callback form (with a
// `lastError` check) for anything that does not return a thenable. Report failure as
// failure — domain-design §9.1 law 2: a surface the user opened deliberately does not
// get to fail quietly.
//
// The storage-directory failure itself turned out to be that simulator's own state:
// after `simctl erase` and a clean setup, settings read back correctly. So this file
// does not exist to work around a platform defect — it exists so that the NEXT
// storage failure, wherever it comes from, cannot masquerade as an empty profile and
// get silently painted over with defaults.

var PageSettings = (() => {
  // Returns {ok, data, error}. `ok:false` means the read FAILED — which is not the
  // same as `{}`, and the caller must not treat it as "no settings yet".
  function rawGet(query) {
    return new Promise((resolve) => {
      let settled = false;
      const done = (r) => { if (!settled) { settled = true; resolve(r); } };
      try {
        const maybe = chrome.storage.local.get(query, (v) => {
          const le = (chrome.runtime && chrome.runtime.lastError) || null;
          if (le) done({ ok: false, data: {}, error: le.message || String(le) });
          else if (v === undefined || v === null) {
            // The shape Safari hands back when the layer is broken. Without the
            // promise form there is no message to show, so say what we know.
            done({ ok: false, data: {}, error: 'storage returned nothing' });
          } else done({ ok: true, data: v, error: null });
        });
        // Safari (and MV3 Chrome) also return a promise. It is the only path that
        // carries the real reason, so let it win when it settles.
        if (maybe && typeof maybe.then === 'function') {
          maybe.then(
            (v) => done({ ok: true, data: v || {}, error: null }),
            (e) => done({ ok: false, data: {}, error: (e && e.message) || String(e) })
          );
        }
      } catch (e) {
        done({ ok: false, data: {}, error: (e && e.message) || String(e) });
      }
    });
  }

  // `keys` is the explicit list the caller needs. Never throws, always settles.
  async function read(keys) {
    const r = await rawGet(keys);
    if (!r.ok) return r;
    const out = {};
    for (const k of keys) if (k in r.data) out[k] = r.data[k];
    return { ok: true, data: out, error: null };
  }

  // Writes with the same truthfulness contract as rawGet: {ok, error}, promise
  // form preferred (it carries the real reason), lastError checked on the
  // callback path, never throws. A write that silently failed is how a session
  // "saves" and then is gone next launch — same incident class as the read side.
  function mutate(run) {
    return new Promise((resolve) => {
      let settled = false;
      const done = (r) => { if (!settled) { settled = true; resolve(r); } };
      try {
        const maybe = run(() => {
          const le = (chrome.runtime && chrome.runtime.lastError) || null;
          if (le) done({ ok: false, error: le.message || String(le) });
          else done({ ok: true, error: null });
        });
        if (maybe && typeof maybe.then === 'function') {
          maybe.then(
            () => done({ ok: true, error: null }),
            (e) => done({ ok: false, error: (e && e.message) || String(e) })
          );
        }
      } catch (e) {
        done({ ok: false, error: (e && e.message) || String(e) });
      }
    });
  }

  function write(items) {
    return mutate((cb) => chrome.storage.local.set(items, cb));
  }

  function removeKeys(keys) {
    return mutate((cb) => chrome.storage.local.remove(keys, cb));
  }

  return { read, rawGet, write, removeKeys };
})();

if (typeof module !== 'undefined' && module.exports) module.exports = PageSettings;


